import java.util.Scanner;

public class Main {
    static final int N = 250100;
    static int mod, m;
    static int[] siz = new int[N], inv = new int[N];
    static DT[] f = new DT[N];

    static class DT {
        int[] a = new int[19];

        DT() {
            for (int i = 0; i < 19; i++) {
                a[i] = 0;
            }
        }
    }

    static int qpow(int x, int y) {
        int ans = 1;
        while (y != 0) {
            if ((y & 1) != 0) {
                ans = (int) ((long) ans * x % mod);
            }
            x = (int) ((long) x * x % mod);
            y >>= 1;
        }
        return ans;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int k = sc.nextInt();
        mod = sc.nextInt();

        if ((n & 1) != 0) {
            System.out.println(qpow(k, n));
            sc.close();
            return;
        }

        m = 0;
        for (int i = 0; i < 18; i++) {
            m += (n >> i) & 1;
        }

        int s = 1;
        for (int i = 0; i <= n; i++) {
            if (i < 2) {
                inv[i] = 1;
            } else {
                inv[i] = (int) ((long) (-mod / i) * inv[mod % i] % mod);
            }
            siz[i] = siz[i >> 1] + (i & 1);
            s = (int) ((long) s * inv[i] % mod);
            if ((i & n) == i) {
                f[i] = new DT();
                f[i].a[siz[i]] = s;
            }
        }

        for (int i = 0; i < 18; i++) {
            if (((n >> i) & 1) != 0) {
                for (int s = n; s != 0; s = (s - 1) & n) {
                    if (((s >> i) & 1) != 0) {
                        DT F = f[s ^ (1 << i)];
                        DT G = f[s];
                        for (int a = 0; a <= m; a++) {
                            for (int b = 0; a + b <= m; b++) {
                                G.a[a + b] = (int) ((G.a[a + b] + (long) F.a[a] * G.a[b]) % mod);
                            }
                        }
                    }
                }
            }
        }

        int[] t = new int[20];
        int[] p = new int[20];

        for (int i = 0; i <= n; i++) {
            if (((i & n) == i)) {
                DT F = f[i];
                for (int a = 0; a <= m; a++) {
                    t[a] = F.a[a];
                    F.a[a] = (a == 0) ? 1 : 0;
                }
                int y = k;
                while (y != 0) {
                    if ((y & 1) != 0) {
                        for (int a = 0; a <= m; a++) {
                            p[a] = F.a[a];
                            F.a[a] = 0;
                        }
                        for (int a = 0; a <= m; a++) {
                            if (t[a] != 0) {
                                for (int b = 0; a + b <= m; b++) {
                                    F.a[a + b] = (int) ((F.a[a + b] + (long) t[a] * p[b]) % mod);
                                }
                            }
                        }
                    }
                    if ((y >>= 1) != 0) {
                        for (int a = 0; a <= m; a++) {
                            p[a] = t[a];
                            t[a] = 0;
                        }
                        for (int a = 0; a <= m; a++) {
                            if (p[a] != 0) {
                                for (int b = 0; a + b <= m; b++) {
                                    t[a + b] = (int) ((t[a + b] + (long) p[a] * p[b]) % mod);
                                }
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < 18; i++) {
            if (((n >> i) & 1) != 0) {
                for (int s = n; s != 0; s = (s - 1) & n) {
                    if (((s >> i) & 1) != 0) {
                        DT F = f[s ^ (1 << i)];
                        DT G = f[s];
                        for (int a = 0; a <= m; a++) {
                            G.a[a] = (G.a[a] - F.a[a]) % mod;
                            if (G.a[a] < 0) G.a[a] += mod;
                        }
                    }
                }
            }
        }

        int sVal = f[n].a[m];
        for (int i = n; i > 0; i--) {
            sVal = (int) ((long) sVal * i % mod);
        }
        int result = ((qpow(k, n) - sVal) % mod + mod) % mod;
        System.out.println(result);
        sc.close();
    }
}

